const e = $json.execution ?? {};
const w = $json.workflow ?? {};
const err = e.error ?? {};

const codigo = Number(err.httpCode);
const codigoValido = Number.isInteger(codigo) && codigo >= 100 && codigo <= 599;

return [{
  json: {
    execution_id: String(e.id ?? `sin-id-${Date.now()}`),
    workflow: String(w.name ?? "desconocido").slice(0, 120),
    nodo: String(e.lastNodeExecuted ?? err.node?.name ?? "desconocido").slice(0, 120),
    codigo_http: codigoValido ? codigo : undefined,
    mensaje: String(err.message || "Error sin mensaje").slice(0, 2000),
    critico: true,
    detalle: {
      execution_url: e.url ?? null,
      retry_of: e.retryOf ?? null,
      modo: e.mode ?? null,
      workflow_id: w.id ?? null,
      descripcion: err.description ?? null
    }
  }
}];

const r = $json;
const DESTINOS = ["<CORREO_ADMIN_1>", "<CORREO_DIRECCION>"];
const url = (r.detalle && r.detalle.execution_url) || "(sin link)";
const texto = [
  "Falló un workflow de n8n.",
  "Workflow: " + (r.workflow || "?"),
  "Nodo: " + (r.nodo || "?"),
  "Código HTTP: " + (r.codigo_http ?? "-"),
  "Mensaje: " + (r.mensaje || "?"),
  "Ejecución: " + (r.execution_id || "?"),
  "Ver en n8n: " + url
].join("\n");
return [{ json: { sendgrid: {
  personalizations: [{ to: DESTINOS.map((email) => ({ email })) }],
  from: { email: "hola@contacto.nano-bridge-mex.com", name: "NANOBRIDGE alertas" },
  subject: "[NANOBRIDGE] Falló " + (r.workflow || "un workflow") + " en " + (r.nodo || "?"),
  content: [{ type: "text/plain", value: texto }],
  tracking_settings: { subscription_tracking: { enable: false }, click_tracking: { enable: false, enable_text: false }, open_tracking: { enable: false } },
  mail_settings: { sandbox_mode: { enable: false } }
} } }];
